examples.setup:
var page by remember { mutableStateOf<String?>("welcome") }
var groups by remember {
    mutableStateOf(
        listOf(
            MonarchPageTreeGroup("basics", "Basics", listOf(MonarchPageTreePage("welcome", "Welcome"), MonarchPageTreePage("setup", "Set up"))),
            MonarchPageTreeGroup("guides", "Guides", emptyList()),
        ),
    )
}

examples.code:
MonarchPageTree(
    groups = groups,
    selected = page,
    onSelect = { page = it },
    modifier = Modifier.height(360.dp),
    onReorder = { next, _ -> groups = next },
    onAddPage = { groupId ->
        groups = groups.map {
            if (it.id == groupId) MonarchPageTreeGroup(it.id, it.label, it.pages + MonarchPageTreePage("new", "")) else it
        }
    },
    onDeletePage = { id ->
        groups = groups.map { g -> MonarchPageTreeGroup(g.id, g.label, g.pages.filterNot { it.id == id }) }
    },
)
